"""Small Studio control for creating a separately reviewed scene draft."""

SCENE_CONTROLS = r"""<dialog id="sceneDialog" aria-labelledby="sceneTitle"><div class="modal-head"><h2 id="sceneTitle">Revise one scene</h2><button class="close" type="button" id="sceneClose" aria-label="Close scene revision">×</button></div><form id="sceneForm"><div class="modal-body"><p class="sub">A saved edit creates a separate draft. The current video and its approvals stay unchanged; the new draft needs script and preview review.</p><img id="sceneSheet" alt="Current storyboard contact sheet" style="display:none;width:100%;height:auto;margin-top:12px;border-radius:8px"><label>Scene<select id="sceneSelect" required></select></label><label>Narration<textarea id="sceneNarration" required></textarea></label><label>Visual subject<input id="sceneSubject" maxlength="200"></label><label>Visual purpose<textarea id="scenePurpose" maxlength="300"></textarea></label><label>Composition<input id="sceneComposition" maxlength="200"></label><label>On-screen text<input id="sceneText" maxlength="500"></label><label>Visual elements, one per line<textarea id="sceneElements"></textarea></label><div id="sceneNotice" class="notice" role="status"></div><div class="actions"><button class="small secondary" type="button" id="sceneCancel">Cancel</button><button class="small" id="sceneSave" type="submit">Create review draft</button></div></div></form></dialog><script>
(()=>{
  let parent=null, packageData=null, reviewedIdentity=null;
  const dialog=document.querySelector('#sceneDialog'), form=document.querySelector('#sceneForm'), select=document.querySelector('#sceneSelect'), notice=document.querySelector('#sceneNotice'), save=document.querySelector('#sceneSave');
  const fields={narration:document.querySelector('#sceneNarration'),visual_subject:document.querySelector('#sceneSubject'),visual_purpose:document.querySelector('#scenePurpose'),composition:document.querySelector('#sceneComposition'),on_screen_text:document.querySelector('#sceneText'),visual_elements:document.querySelector('#sceneElements')};
  const close=()=>dialog.close();document.querySelector('#sceneClose').onclick=close;document.querySelector('#sceneCancel').onclick=close;
  function showScene(){if(!packageData)return;const scene=packageData.scene_plans.find(item=>item.scene_id===select.value),section=packageData.script_sections.find(item=>item.scene_id===select.value);if(!scene||!section){notice.textContent='This scene has no matching narration section.';save.disabled=true;return;}fields.narration.value=section.narration;fields.visual_subject.value=scene.visual_subject||'';fields.visual_purpose.value=scene.visual_purpose||'';fields.composition.value=scene.composition||'';fields.on_screen_text.value=scene.on_screen_text||'';fields.visual_elements.value=(scene.visual_elements||[]).join('\n');save.disabled=false;notice.textContent='Edit one scene and create a new review draft.';}
  select.onchange=showScene;
  async function open(job){parent=job.id;packageData=null;reviewedIdentity=null;notice.textContent='Loading scene and approved script…';select.replaceChildren();save.disabled=true;const sheet=document.querySelector('#sceneSheet');sheet.style.display='none';sheet.removeAttribute('src');dialog.showModal();try{const response=await fetch(`/api/jobs/${job.id}/script`);if(!response.ok)throw Error(await response.text());const data=await response.json();packageData=data.package;reviewedIdentity=data.reviewed_identity;for(const item of packageData.scene_plans){select.append(Object.assign(document.createElement('option'),{value:item.scene_id,textContent:item.scene_id+' · '+(item.visual_subject||item.visual_type)}));}if(job.artifacts.includes('contact_sheet_001')){sheet.src=`/api/jobs/${job.id}/artifacts/contact_sheet_001`;sheet.style.display='block';}showScene();}catch(error){notice.textContent='Could not load scene: '+error.message;}}
  form.onsubmit=async event=>{event.preventDefault();if(!parent||!reviewedIdentity||!packageData)return;save.disabled=true;save.textContent='Saving draft…';notice.textContent='Creating a new review draft…';const values={scene_id:select.value,expected_content_sha256:reviewedIdentity,actor:'local-dashboard',narration:fields.narration.value.trim(),on_screen_text:fields.on_screen_text.value.trim(),visual_elements:fields.visual_elements.value.split('\n').map(value=>value.trim()).filter(Boolean)};for(const key of ['visual_subject','visual_purpose','composition']){const value=fields[key].value.trim();if(value)values[key]=value;}try{const response=await fetch(`/api/jobs/${parent}/scene-revisions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});if(!response.ok)throw Error(await response.text());const draft=await response.json();notice.textContent='Draft '+draft.job_id.slice(0,8)+' saved. Review and approve its exact script before rendering; the original video is unchanged.';save.textContent='Draft saved';}catch(error){notice.textContent='Could not create draft: '+error.message;save.disabled=false;save.textContent='Create review draft';}};
  async function decorate(){let jobs;try{const response=await fetch('/api/jobs');if(!response.ok)return;jobs=new Map((await response.json()).map(job=>[job.id,job]));}catch(_){return;}for(const card of document.querySelectorAll('.job[data-job-id]')){const job=jobs.get(card.dataset.jobId);if(!job||!job.artifacts.includes('content_package')||!['script_approval_required','preview_ready','final_ready','publication_approval_required'].includes(job.state)||card.querySelector('.scene-revision'))continue;const actions=card.querySelector('.actions');if(!actions)continue;const button=document.createElement('button');button.type='button';button.className='small secondary scene-revision';button.textContent='Revise one scene';button.onclick=()=>open(job);actions.append(button);}}
  decorate();setInterval(decorate,4000);
})();
</script>"""
